import argparse
import csv
import json
from datetime import date


def parse_args():
    parser = argparse.ArgumentParser(
        usage="%(prog)s sales.csv [--format text|json] [--since YYYY-MM-DD]"
    )
    parser.add_argument("csv_file")
    parser.add_argument("--format", choices=("text", "json"), default="text")
    parser.add_argument("--since", type=date.fromisoformat, metavar="YYYY-MM-DD")
    return parser.parse_args()


def build_report(path, since=None):
    total_revenue = 0
    total_tax = 0
    by_region = {}
    by_product = {}
    rows = 0

    with open(path, newline="") as source:
        reader = csv.reader(source)
        next(reader, None)
        for fields in reader:
            if len(fields) < 5:
                continue
            if since is not None:
                try:
                    sale_date = date.fromisoformat(fields[0].strip())
                except ValueError:
                    continue
                if sale_date < since:
                    continue
            try:
                units = int(fields[3])
                unit_price = float(fields[4])
            except (ValueError, IndexError):
                continue

            amount = units * unit_price
            if units >= 50:
                amount -= amount * 0.1
            elif units >= 10:
                amount -= amount * 0.05

            region = fields[1]
            product = fields[2]
            tax_rate = {"north": 0.07, "south": 0.05, "east": 0.06, "west": 0.08}.get(region, 0)
            total_revenue += amount
            total_tax += amount * tax_rate
            by_region[region] = by_region.get(region, 0) + amount
            by_product[product] = by_product.get(product, 0) + amount
            rows += 1

    top_product = None
    top_amount = 0
    for product, amount in by_product.items():
        if amount > top_amount:
            top_product, top_amount = product, amount

    return {
        "rows": rows,
        "total_revenue": round(total_revenue, 2),
        "total_tax": round(total_tax, 2),
        "by_region": {key: round(by_region[key], 2) for key in sorted(by_region)},
        "by_product": {key: round(by_product[key], 2) for key in sorted(by_product)},
        "top_product": top_product,
    }, top_amount


def print_text(report, top_amount):
    print("SALES REPORT")
    print("============")
    print("Rows: " + str(report["rows"]))
    print("Total revenue: " + str(report["total_revenue"]))
    print("Total tax: " + str(report["total_tax"]))
    print("")
    print("By region:")
    for key, amount in report["by_region"].items():
        print("  " + key + ": " + str(amount))
    print("")
    print("By product:")
    for key, amount in report["by_product"].items():
        print("  " + key + ": " + str(amount))
    print("")
    print("Top product: " + str(report["top_product"]) + " (" + str(round(top_amount, 2)) + ")")


def main():
    args = parse_args()
    report, top_amount = build_report(args.csv_file, args.since)
    if args.format == "json":
        print(json.dumps(report))
    else:
        print_text(report, top_amount)


if __name__ == "__main__":
    main()
